import{_ as n,o as a,c as t,a3 as l,j as e,a as i}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/reportdesigner/tutorials-reporting-fehler-grafik.png",g=JSON.parse('{"title":"Grafikfehler in Reports beheben","description":"","frontmatter":{"title":"Grafikfehler in Reports beheben","source_pageid":1360,"source_revision":6692},"headers":[],"relativePath":"reporting/reportdesigner/problem-bei-der-verwendung-von-grafiken-tutorial.md","filePath":"reporting/reportdesigner/problem-bei-der-verwendung-von-grafiken-tutorial.md"}'),d={name:"reporting/reportdesigner/problem-bei-der-verwendung-von-grafiken-tutorial.md"};function s(h,r,f,p,u,b){return a(),t("div",null,[...r[0]||(r[0]=[l(`<h1 id="grafikfehler-in-reports-beheben" tabindex="-1">Grafikfehler in Reports beheben <a class="header-anchor" href="#grafikfehler-in-reports-beheben" aria-label="Permalink to &quot;Grafikfehler in Reports beheben&quot;">​</a></h1><p>Wenn ein Report mit der Meldung „Ungültige Graphik“ abbricht, prüfen Sie das Bildformat und die Eigenschaft ParentDataPipeline des betroffenen Bildes.</p><h2 id="fehlerbild" tabindex="-1">Fehlerbild <a class="header-anchor" href="#fehlerbild" aria-label="Permalink to &quot;Fehlerbild&quot;">​</a></h2><p>Die Reportausgabe kann mit folgender Meldung abbrechen:</p><pre><code> Fehler bei der Ausgabe:
 Kann den Bericht nicht generieren.
 
 Ungültige Graphik.
</code></pre><h2 id="bildformat-und-eigenschaft-prufen" tabindex="-1">Bildformat und Eigenschaft prüfen <a class="header-anchor" href="#bildformat-und-eigenschaft-prufen" aria-label="Permalink to &quot;Bildformat und Eigenschaft prüfen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/tutorials-reporting-fehler-grafik.png"><img src="`+o+'" alt="Kommt es zu dem hier behandelten Fehler, kann bei dem betreffenden Bild, hier im Beispiel DBImage1 die ParentDataPipeline deaktiviert werden." loading="lazy"></a></p><p><em>Kommt es zu dem hier behandelten Fehler, kann bei dem betreffenden Bild, hier im Beispiel DBImage1 die ParentDataPipeline deaktiviert werden.</em></p><ol><li>Verwenden Sie Bilder im Format JPG oder PNG. Für Logos mit klaren Linien und Flächen eignet sich das verlustlose PNG-Format; Schülerbilder speichern Sie vorzugsweise als JPG.</li><li>Öffnen Sie den Report im Reportbaukasten und wählen Sie das betroffene Bild aus.</li><li>Entfernen Sie bei diesem Bild den Haken bei <strong>ParentDataPipeline</strong>.</li><li>Prüfen Sie die Reportausgabe erneut.</li></ol>',9),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),i("Hinweis – Mehrere Bilder im Report")]),e("p",null,"Bei mehreren Bildern kann die Einstellung für alle Bilder erforderlich sein. Prüfen Sie gegebenenfalls, welche Bilder beziehungsweise Bildkombinationen den Fehler auslösen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Problem_bei_der_Verwendung_von_Grafiken_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),i(" · Quellrevision 6692.")],-1)])])}const m=n(d,[["render",s]]);export